<?php require_once __DIR__.'/../includes/auth.php';requireLecturer();$q=db()->prepare('SELECT a.*,b.batch_code,s.subject_name,se.semester_name FROM attendance_sessions a JOIN batch_subjects bs ON bs.id=a.batch_subject_id JOIN batches b ON b.id=bs.batch_id JOIN subjects s ON s.id=bs.subject_id JOIN semesters se ON se.id=bs.semester_id WHERE a.created_by=? ORDER BY a.attendance_date DESC,a.id DESC');$q->execute([$_SESSION['user']['id']]);$title='Attendance History';require __DIR__.'/../includes/header.php';?><section class="panel table-wrap"><table><tr><th>Date</th><th>Batch</th><th>Semester</th><th>Subject</th><th>Lecture</th><th>Type</th><th></th></tr><?php foreach($q as $a):?><tr><td><?=e($a['attendance_date'])?></td><td><?=e($a['batch_code'])?></td><td><?=e($a['semester_name'])?></td><td><?=e($a['subject_name'])?></td><td><?=str_pad((string)$a['lecture_number'],2,'0',STR_PAD_LEFT)?></td><td><?=e(ucfirst($a['session_type']))?></td><td><a class="button secondary" href="session.php?id=<?=$a['id']?>">View</a></td></tr><?php endforeach?></table></section><?php require __DIR__.'/../includes/footer.php';?>
